INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('31bec646-5424-5e5f-ba75-db146df627e9', 'India Companies Bill', 'The Companies Bill', 'This Bill makes amendments to the existing Companies Act in regards of corporate governance, however, no reporting developments have been added to this update.', 'This Bill makes amendments to the existing Companies Act in regards of corporate governance, however, no reporting developments have been added to this update.', 'This Bill makes amendments to the existing Companies Act in regards of corporate governance, however, no reporting developments have been added to this update.', 'India', 'climate', 'in_force', '2012-01-01'::date, 'India', 'https://www.carrotsandsticks.org/policies/78_20', ARRAY['regulations', 'india', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2ad36d41-0775-5f97-a9f8-1576d6efdec3', 'India Good Governance -- Guidance', 'Good Governance -- Guidance 2012', 'This standard provides guidance on good governance practices by an organization irrespective of its size, type, location or nature of activities. It is intended to provide assistance to organizations engaged in public private partnerships (PPP), having varying governance structures.', 'This standard provides guidance on good governance practices by an organization irrespective of its size, type, location or nature of activities. It is intended to provide assistance to organizations engaged in public private partnerships (PPP), having varying governance structures.', 'This standard provides guidance on good governance practices by an organization irrespective of its size, type, location or nature of activities. It is intended to provide assistance to organizations engaged in public private partnerships (PPP), having varying governance structures.', 'India', 'nature', 'in_force', '2012-01-01'::date, 'India', 'https://www.carrotsandsticks.org/policies/78_34', ARRAY['guidance_frameworks', 'india', 'sdg17', 'mandatory', 'sdg16', 'disclosure', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5ef1afae-b480-57a9-b67d-0961371286ae', 'India National Voluntary Guidelines on Social, Environmental & Economic', 'National Voluntary Guidelines on Social, Environmental & Economic Responsibilities of Business 2011', 'These updated guidelines, directed at all business types and sizes, provide a basic framework that may be adopted voluntarily in order to address the interests of various stakeholders, including employees, customers and investors.', 'These updated guidelines, directed at all business types and sizes, provide a basic framework that may be adopted voluntarily in order to address the interests of various stakeholders, including employees, customers and investors.', 'These updated guidelines, directed at all business types and sizes, provide a basic framework that may be adopted voluntarily in order to address the interests of various stakeholders, including employees, customers and investors.', 'India', 'governance', 'in_force', '2011-01-01'::date, 'India', 'https://www.carrotsandsticks.org/policies/78_11', ARRAY['india', 'guidance_frameworks', 'voluntary', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f3fbc863-a2d7-52ec-a189-15734069675e', 'India E-Waste (Management and Handling) Rules', 'E-Waste (Management and Handling) Rules, 2011', 'A set of rules that shall apply to every producer, consumer, or bulk consumer involved in the manufacture, sale, purchase and processing of electrical and electronic equipment or components.', 'A set of rules that shall apply to every producer, consumer, or bulk consumer involved in the manufacture, sale, purchase and processing of electrical and electronic equipment or components.', 'A set of rules that shall apply to every producer, consumer, or bulk consumer involved in the manufacture, sale, purchase and processing of electrical and electronic equipment or components.', 'India', 'climate', 'in_force', '2011-01-01'::date, 'India', 'https://www.carrotsandsticks.org/policies/78_48', ARRAY['regulations', 'india', 'sdg9', 'mandatory', 'sdg12', 'disclosure', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6356a54a-ebd2-5220-89ff-bf1ce498b395', 'India National Green Tribunal Act', 'The National Green Tribunal Act 2010', 'An Act to provide for the establishment of a National Green Tribunal for the effective and expeditious disposal of cases relating to environmental protection and conservation of forests and other natural resources including enforcement of any legal right relating to environment and giving relief and compensation for damages to persons and property and for matters connected therewith or incidental thereto.', 'An Act to provide for the establishment of a National Green Tribunal for the effective and expeditious disposal of cases relating to environmental protection and conservation of forests and other natural resources including enforcement of any legal right relating to environment and giving relief and compensation for damages to persons and property and for matters connected therewith or incidental thereto.', 'An Act to provide for the establishment of a National Green Tribunal for the effective and expeditious disposal of cases relating to environmental protection and conservation of forests and other natural resources including enforcement of any legal right relating to environment and giving relief and compensation for damages to persons and property and for matters connected therewith or incidental thereto.', 'India', 'nature', 'in_force', '2010-01-01'::date, 'India', 'https://www.carrotsandsticks.org/policies/78_2', ARRAY['other sustainability policy', 'regulations', 'india', 'mandatory', 'sdg16', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d42ff19e-d164-5ce7-b0cd-f598911a29cd', 'India Corporate Social Responsibility Voluntary Guidelines', 'Corporate Social Responsibility Voluntary Guidelines', 'The Voluntary Guidelines state that CSR initiatives of Indian companies should become integral part of their overall business policy. The Guidelines set out six core elements for companies to address, including respect for workers’ rights and welfare, human rights, and the environment.', 'The Voluntary Guidelines state that CSR initiatives of Indian companies should become integral part of their overall business policy. The Guidelines set out six core elements for companies to address, including respect for workers’ rights and welfare, human rights, and the environment.', 'The Voluntary Guidelines state that CSR initiatives of Indian companies should become integral part of their overall business policy. The Guidelines set out six core elements for companies to address, including respect for workers’ rights and welfare, human rights, and the environment.', 'India', 'social', 'in_force', '2009-01-01'::date, 'India', 'https://www.carrotsandsticks.org/policies/78_7', ARRAY['guidance_frameworks', 'sdg8', 'other sustainability policy', 'india', 'sdg16', 'sdg9', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('696c76a3-452f-57bd-ad80-d9f22ad66cbc', 'India Notification of the Hazardious Material Rules', 'Notification of the Hazardious Material Rules', 'The Rules lay down corresponding duties of various authorities such as MoEF, CPCB, State/UT Govts., SPCBs/PCCs, DGFT, Port Authority and Custom Authority while State Pollution Control Boards/ Pollution Control Committees have been designated with wider responsibilities touching across almost every aspect of Hazardous wastes generation, handing and their disposal.', 'The Rules lay down corresponding duties of various authorities such as MoEF, CPCB, State/UT Govts., SPCBs/PCCs, DGFT, Port Authority and Custom Authority while State Pollution Control Boards/ Pollution Control Committees have been designated with wider responsibilities touching across almost every aspect of Hazardous wastes generation, handing and their disposal.', 'The Rules lay down corresponding duties of various authorities such as MoEF, CPCB, State/UT Govts., SPCBs/PCCs, DGFT, Port Authority and Custom Authority while State Pollution Control Boards/ Pollution Control Committees have been designated with wider responsibilities touching across almost every aspect of Hazardous wastes generation, handing and their disposal.', 'India', 'climate', 'in_force', '2008-01-01'::date, 'India', 'https://www.carrotsandsticks.org/policies/78_49', ARRAY['sdg13', 'india', 'mandatory', 'mandatory_regulations', 'sdg12', 'disclosure', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('559ff112-fc42-5349-a2ec-12eb992c520b', 'India Corporate Social Responsibility, Sustainable Development and Non-Financial Reporting', 'Corporate Social Responsibility, Sustainable Development and Non-Financial Reporting - Role of Banks', 'The notification introduces the concepts of CSR, SD and NFR, the felt need therefor, financial sector initiatives worldwide in the wake thereof and other related issues and underscore the importance of the issues involved and the global initiatives being taken in this regard.', 'The notification introduces the concepts of CSR, SD and NFR, the felt need therefor, financial sector initiatives worldwide in the wake thereof and other related issues and underscore the importance of the issues involved and the global initiatives being taken in this regard.', 'The notification introduces the concepts of CSR, SD and NFR, the felt need therefor, financial sector initiatives worldwide in the wake thereof and other related issues and underscore the importance of the issues involved and the global initiatives being taken in this regard.', 'India', 'climate', 'in_force', '2007-01-01'::date, 'India', 'https://www.carrotsandsticks.org/policies/78_28', ARRAY['sdg13', 'india', 'mandatory', 'sdg16', 'mandatory_regulations', 'sdg12', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('dc3112b4-a8e1-5215-83fc-b4420d11bd7e', 'India Notification of the Environment (Protection) Rules', 'Notification of the Environment (Protection) Rules', 'The objective of EIA Notification 2006 is to address the limitations in the old EIA Notification (1994). Therefore, various modifications have been incorporated in the old Notification, which the ministry claims have been done after taking into account the feedback from the different stakeholders.', 'The objective of EIA Notification 2006 is to address the limitations in the old EIA Notification (1994). Therefore, various modifications have been incorporated in the old Notification, which the ministry claims have been done after taking into account the feedback from the different stakeholders.', 'The objective of EIA Notification 2006 is to address the limitations in the old EIA Notification (1994). Therefore, various modifications have been incorporated in the old Notification, which the ministry claims have been done after taking into account the feedback from the different stakeholders.', 'India', 'climate', 'in_force', '2006-01-01'::date, 'India', 'https://www.carrotsandsticks.org/policies/78_33', ARRAY['sdg13', 'india', 'mandatory', 'mandatory_regulations', 'disclosure', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('203dc2be-2c80-5507-99fa-37e8beaf6263', 'India Charter on Corporate Responsibility for Environmental Protection (CREP)', 'Charter on Corporate Responsibility for Environmental Protection (CREP)', 'Ministry of Environment & Forest (MoEF) launched the Charter on "Corporate Responsibility for Environmental Protection (CREP)" in March 2003 with the purpose to go beyond the compliance of regulatory norms for prevention & control of pollution through various measures including waste minimization, in-plant process control & adoption of clean technologies. The Charter set targets concerning conservation of water, energy, recovery of chemicals, reduction in pollution, elimination of toxic pollutants, process & management of residues that are required to be disposed off in an environmentally sound manner. The Charter enlists the action points for pollution control for various categories of highly polluting industries.', 'Ministry of Environment & Forest (MoEF) launched the Charter on "Corporate Responsibility for Environmental Protection (CREP)" in March 2003 with the purpose to go beyond the compliance of regulatory norms for prevention & control of pollution through various measures including waste minimization, in-plant process control & adoption of clean technologies. The Charter set targets concerning conservation of water, energy, recovery of chemicals, reduction in pollution, elimination of toxic pollutants, process & management of residues that are required to be disposed off in an environmentally sound manner. The Charter enlists the action points for pollution control for various categories of highly polluting industries.', 'Ministry of Environment & Forest (MoEF) launched the Charter on "Corporate Responsibility for Environmental Protection (CREP)" in March 2003 with the purpose to go beyond the compliance of regulatory norms for prevention & control of pollution through various measures including waste minimization, in-plant process control & adoption of clean technologies. The Charter set targets concerning conservation of water, energy, recovery of chemicals, reduction in pollution, elimination of toxic pollutants, process & management of residues that are required to be disposed off in an environmentally sound manner. The Charter enlists the action points for pollution control for various categories of highly polluting industries.', 'India', 'climate', 'in_force', '2003-01-01'::date, 'India', 'https://www.carrotsandsticks.org/policies/78_6', ARRAY['sdg13', 'india', 'sdg7', 'mandatory', 'sdg6', 'mandatory_regulations', 'sdg12', 'disclosure', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ce7cd7c9-1b3e-508a-9b6b-30229c3c8a6d', 'India Report of the Kumar Mangalam Birla Committee', 'Report of the Kumar Mangalam Birla Committee on Corporate Governance', 'At the heart of the Committee''s report is the set of recommendations which distinguishes the responsibilities and obligations of the boards and the management in instituting the systems for good corporate governance and emphasises the rights of shareholders in demanding corporate governance.', 'At the heart of the Committee''s report is the set of recommendations which distinguishes the responsibilities and obligations of the boards and the management in instituting the systems for good corporate governance and emphasises the rights of shareholders in demanding corporate governance.', 'At the heart of the Committee''s report is the set of recommendations which distinguishes the responsibilities and obligations of the boards and the management in instituting the systems for good corporate governance and emphasises the rights of shareholders in demanding corporate governance.', 'India', 'climate', 'in_force', '2000-01-01'::date, 'India', 'https://www.carrotsandsticks.org/policies/78_17', ARRAY['india', 'mandatory', 'sdg16', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('72f59121-aa03-558c-a112-830dba6cf8db', 'India Notification of the Ozone Depleting Substances Rules', 'Notification of the Ozone Depleting Substances Rules', 'The Ozone Depleting Substances (Regulation and Control) Rules of 2000 by the Ministry of Environment and Forests in India aim to regulate the production and consumption of ozone-depleting substances in accordance with the Environment (Protection) Act of 1986 and the Montreal Protocol. The rules set limits on production and consumption, require registration with specified authorities, and mandate compliance with reduction targets. Financial assistance recipients must adhere to agreed production limits. Non-compliance results in penalties. The policy is mandatory and covers the ozone-depleting substance industry.', 'The Ozone Depleting Substances (Regulation and Control) Rules of 2000 by the Ministry of Environment and Forests in India aim to regulate the production and consumption of ozone-depleting substances in accordance with the Environment (Protection) Act of 1986 and the Montreal Protocol. The rules set limits on production and consumption, require registration with specified authorities, and mandate compliance with reduction targets. Financial assistance recipients must adhere to agreed production limits. Non-compliance results in penalties. The policy is mandatory and covers the ozone-depleting substance industry.', 'The Ozone Depleting Substances (Regulation and Control) Rules of 2000 by the Ministry of Environment and Forests in India aim to regulate the production and consumption of ozone-depleting substances in accordance with the Environment (Protection) Act of 1986 and the Montreal Protocol. The rules set limits on production and consumption, require registration with specified authorities, and mandate compliance with reduction targets. Financial assistance recipients must adhere to agreed production limits. Non-compliance results in penalties. The policy is mandatory and covers the ozone-depleting substance industry.', 'India', 'climate', 'in_force', '2000-01-01'::date, 'India', 'https://www.carrotsandsticks.org/policies/78_50', ARRAY['sdg13', 'regulations', 'india', 'sdg9', 'mandatory', 'sdg12', 'disclosure', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
