INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2592b06a-e7a8-5d84-b5af-4b77491db46d', 'Desirable Corporate Governance in India. A Code', 'Desirable Corporate Governance in India. A Code', 'This instrument develops and promotes a code for Corporate Governance to be adopted and followed by Indian companies, be these in the Private Sector, the Public Sector, Banks or Financial Institutions, all of which are corporate entities.', 'This instrument develops and promotes a code for Corporate Governance to be adopted and followed by Indian companies, be these in the Private Sector, the Public Sector, Banks or Financial Institutions, all of which are corporate entities.', 'This instrument develops and promotes a code for Corporate Governance to be adopted and followed by Indian companies, be these in the Private Sector, the Public Sector, Banks or Financial Institutions, all of which are corporate entities.', 'India', 'governance', 'in_force', '1998-01-01'::date, 'India', 'https://www.carrotsandsticks.org/policies/78_15', ARRAY['india', 'mandatory', 'sdg16', 'mandatory_regulations', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b3eb60de-48d0-584b-9171-bc530f9a4936', 'Indonesia Green Taxonomy Edition 1.0', 'Indonesia Green Taxonomy Edition 1.0 -- 2022', 'The Indonesia Green Taxonomy Edition 1.0 will be used as: (1) the basis for the development of incentive and disincentive policy of various ministries and institutions, including OJK; and (2) guidelines for information openness, risk management, and development of innovative sustainable finance products and/or services for FSS and issuers.', 'The Indonesia Green Taxonomy Edition 1.0 will be used as: (1) the basis for the development of incentive and disincentive policy of various ministries and institutions, including OJK; and (2) guidelines for information openness, risk management, and development of innovative sustainable finance products and/or services for FSS and issuers.', 'The Indonesia Green Taxonomy Edition 1.0 will be used as: (1) the basis for the development of incentive and disincentive policy of various ministries and institutions, including OJK; and (2) guidelines for information openness, risk management, and development of innovative sustainable finance products and/or services for FSS and issuers.', 'Indonesia', 'climate', 'in_force', '2022-01-01'::date, 'Indonesia', 'https://www.carrotsandsticks.org/policies/79_69', ARRAY['sdg2', 'indonesia', 'sdg14', 'sdg9', 'sdg7', 'sdg11', 'mandatory', 'mandatory_regulations', 'disclosure', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('aa6b49a6-31fd-5acd-bc1d-aa71949e3414', 'Indonesian Corporate Governance Manual', 'Indonesian Corporate Governance Manual. 2nd Edition 2018', 'The Indonesia Corporate Governance Manual discusses key corporate governance elements that have been contextualized to take into account current Indonesian laws and regulations as well as international best practices. While it is recommended to read the entire Manual to gain a full understanding of the corporate governance framework in Indonesia, it is not necessary to read all the chapters in chronological order. The Manual includes examples, illustrations, and checklists to aid clarity and understanding.', 'The Indonesia Corporate Governance Manual discusses key corporate governance elements that have been contextualized to take into account current Indonesian laws and regulations as well as international best practices. While it is recommended to read the entire Manual to gain a full understanding of the corporate governance framework in Indonesia, it is not necessary to read all the chapters in chronological order. The Manual includes examples, illustrations, and checklists to aid clarity and understanding.', 'The Indonesia Corporate Governance Manual discusses key corporate governance elements that have been contextualized to take into account current Indonesian laws and regulations as well as international best practices. While it is recommended to read the entire Manual to gain a full understanding of the corporate governance framework in Indonesia, it is not necessary to read all the chapters in chronological order. The Manual includes examples, illustrations, and checklists to aid clarity and understanding.', 'Indonesia', 'climate', 'in_force', '2018-01-01'::date, 'Indonesia', 'https://www.carrotsandsticks.org/policies/79_2', ARRAY['indonesia', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a4a96e65-d3c2-5f64-acb6-6609a5fe47d9', 'Indonesia Regulation of the President Number 83, 2018', 'Regulation of the President of the Republic of Indonesia Number 83, 2018, concerning Marine Waste Management', 'The Regulation of the President of the Republic of Indonesia Number 83, 2018, focuses on Marine Waste Management to address pollution, environmental damage, and risks to human health caused by sea rubbish, particularly plastic waste. It aims to reduce plastic waste in the sea by 70% by 2025 through comprehensive measures, integrated planning, and strengthening of waste management activities. The policy outlines a National Action Plan for Handling Marine Garbage for 2018-2025, emphasizing stakeholder awareness, land-based waste management, coastal and sea debris cleanup, funding mechanisms, and law enforcement.', 'The Regulation of the President of the Republic of Indonesia Number 83, 2018, focuses on Marine Waste Management to address pollution, environmental damage, and risks to human health caused by sea rubbish, particularly plastic waste. It aims to reduce plastic waste in the sea by 70% by 2025 through comprehensive measures, integrated planning, and strengthening of waste management activities. The policy outlines a National Action Plan for Handling Marine Garbage for 2018-2025, emphasizing stakeholder awareness, land-based waste management, coastal and sea debris cleanup, funding mechanisms, and law enforcement.', 'The Regulation of the President of the Republic of Indonesia Number 83, 2018, focuses on Marine Waste Management to address pollution, environmental damage, and risks to human health caused by sea rubbish, particularly plastic waste. It aims to reduce plastic waste in the sea by 70% by 2025 through comprehensive measures, integrated planning, and strengthening of waste management activities. The policy outlines a National Action Plan for Handling Marine Garbage for 2018-2025, emphasizing stakeholder awareness, land-based waste management, coastal and sea debris cleanup, funding mechanisms, and law enforcement.', 'Indonesia', 'nature', 'in_force', '2018-01-01'::date, 'Indonesia', 'https://www.carrotsandsticks.org/policies/79_54', ARRAY['indonesia', 'sdg14', 'other sustainability policy', 'regulations', 'mandatory', 'sdg12', 'sdg15', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b1b2183e-d99a-5c42-91b2-f37273f4260e', 'Indonesia Copy of financial services authority regulation number 51', 'Copy of financial services authority regulation number 51 /POJK.03/2017', 'A regulation on the application of sustainable finance for financial services institutions, issuers, and public companies.', 'A regulation on the application of sustainable finance for financial services institutions, issuers, and public companies.', 'A regulation on the application of sustainable finance for financial services institutions, issuers, and public companies.', 'Indonesia', 'climate', 'in_force', '2017-01-01'::date, 'Indonesia', 'https://www.carrotsandsticks.org/policies/79_12', ARRAY['indonesia', 'regulations', 'mandatory', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('015e3977-a474-5068-b33f-e01c9144ecf4', 'Indonesia Regulation of the President , , 2017. About', 'Regulation of the President of the Republic of Indonesia, No 97, 2017. About National Policies and Strategies for Household Waste and Waste Management, a Kind of Household Waste.', 'The Regulation of the President of the Republic of Indonesia, No 97, 2017, focuses on National Policies and Strategies for Household Waste and Waste Management, specifically targeting the reduction and handling of household waste and similar waste. It outlines policy directions, requirements for waste reduction, recycling, and coordination between Central and Regional Governments. The policy aims to increase leadership capacity, strengthen business commitments, and involve communities in waste management efforts.', 'The Regulation of the President of the Republic of Indonesia, No 97, 2017, focuses on National Policies and Strategies for Household Waste and Waste Management, specifically targeting the reduction and handling of household waste and similar waste. It outlines policy directions, requirements for waste reduction, recycling, and coordination between Central and Regional Governments. The policy aims to increase leadership capacity, strengthen business commitments, and involve communities in waste management efforts.', 'The Regulation of the President of the Republic of Indonesia, No 97, 2017, focuses on National Policies and Strategies for Household Waste and Waste Management, specifically targeting the reduction and handling of household waste and similar waste. It outlines policy directions, requirements for waste reduction, recycling, and coordination between Central and Regional Governments. The policy aims to increase leadership capacity, strengthen business commitments, and involve communities in waste management efforts.', 'Indonesia', 'circularity', 'in_force', '2017-01-01'::date, 'Indonesia', 'https://www.carrotsandsticks.org/policies/79_15', ARRAY['indonesia', 'regulations', 'sdg11', 'mandatory', 'sdg12', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e8532d9c-c7de-58a3-a27c-2a32e2c66a3a', 'Indonesia Number 51/POJK. about Sustainable Finance application for Financial', 'Number 51/POJK.03/2017 about Sustainable Finance application for Financial Services Institutions, Issuers, and Public Companies', 'Regulation of the Financial Services Authority concerning the Implementation of Sustainable Finance for Financial Services Institutions, Issuers, and Public Companies.', 'Regulation of the Financial Services Authority concerning the Implementation of Sustainable Finance for Financial Services Institutions, Issuers, and Public Companies.', 'Regulation of the Financial Services Authority concerning the Implementation of Sustainable Finance for Financial Services Institutions, Issuers, and Public Companies.', 'Indonesia', 'climate', 'in_force', '2017-01-01'::date, 'Indonesia', 'https://www.carrotsandsticks.org/policies/79_20', ARRAY['indonesia', 'sdg13', 'regulations', 'mandatory', 'sdg16', 'sdg12', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('31af1d58-be11-5d0e-a8a5-6e53d2c2bd01', 'Indonesia Regulation of the Minister of State-owned Enterprises Number', 'Regulation of the Minister of State-owned Enterprises of the Republic of Indonesia Number Per - 02/mbu/7/2017', 'Second Amendment to the regulations on state-owned enterprises. Focused on partnership program and environmental development program.', 'Second Amendment to the regulations on state-owned enterprises. Focused on partnership program and environmental development program.', 'Second Amendment to the regulations on state-owned enterprises. Focused on partnership program and environmental development program.', 'Indonesia', 'climate', 'in_force', '2017-01-01'::date, 'Indonesia', 'https://www.carrotsandsticks.org/policies/79_6', ARRAY['indonesia', 'other sustainability policy', 'regulations', 'sdg17', 'mandatory']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('378bfb7e-52ca-5ef6-9476-891216bb56ce', 'Indonesia Financial services authority regulation number 29 /POJK', 'Financial services authority regulation number 29 /POJK.04/2016', 'The Financial Services Authority regulation number 29/POJK.04/2016 from Indonesia sets rules for Issuers'' or Public Companies'' annual reporting. It requires preparing an Annual Report containing financial data, governance information, social and environmental responsibility details, and more. The report must be printed, bound, and presented in Indonesian, with some information also in a foreign language. The Annual Report needs to be submitted to the Financial Services Authority annually after the financial year ends. The policy aims to enhance transparency, accountability, and reporting standards for companies in Indonesia.', 'The Financial Services Authority regulation number 29/POJK.04/2016 from Indonesia sets rules for Issuers'' or Public Companies'' annual reporting. It requires preparing an Annual Report containing financial data, governance information, social and environmental responsibility details, and more. The report must be printed, bound, and presented in Indonesian, with some information also in a foreign language. The Annual Report needs to be submitted to the Financial Services Authority annually after the financial year ends. The policy aims to enhance transparency, accountability, and reporting standards for companies in Indonesia.', 'The Financial Services Authority regulation number 29/POJK.04/2016 from Indonesia sets rules for Issuers'' or Public Companies'' annual reporting. It requires preparing an Annual Report containing financial data, governance information, social and environmental responsibility details, and more. The report must be printed, bound, and presented in Indonesian, with some information also in a foreign language. The Annual Report needs to be submitted to the Financial Services Authority annually after the financial year ends. The policy aims to enhance transparency, accountability, and reporting standards for companies in Indonesia.', 'Indonesia', 'climate', 'in_force', '2016-01-01'::date, 'Indonesia', 'https://www.carrotsandsticks.org/policies/79_3', ARRAY['indonesia', 'other sustainability policy', 'regulations', 'mandatory', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0223ea77-95d4-5f79-b398-f5ad63a4a195', 'Indonesia Financial Services Authority Circular Letter Number 30 /seojk', 'Financial Services Authority Circular Letter Number 30 /seojk.04/2016', 'An annual report serves as the BOD and BOC''s accountability report as well as a source of information for investors hence the OJK intends to increase the quality and accessibility of the annual reports. To achieve this, the OJK provides several additional provisions for the preparation and submission of annual reports. Under the new rule, the OJK also sets administrative sanctions if listed and public companies fail to submit an annual report or breach the rule.', 'An annual report serves as the BOD and BOC''s accountability report as well as a source of information for investors hence the OJK intends to increase the quality and accessibility of the annual reports. To achieve this, the OJK provides several additional provisions for the preparation and submission of annual reports. Under the new rule, the OJK also sets administrative sanctions if listed and public companies fail to submit an annual report or breach the rule.', 'An annual report serves as the BOD and BOC''s accountability report as well as a source of information for investors hence the OJK intends to increase the quality and accessibility of the annual reports. To achieve this, the OJK provides several additional provisions for the preparation and submission of annual reports. Under the new rule, the OJK also sets administrative sanctions if listed and public companies fail to submit an annual report or breach the rule.', 'Indonesia', 'climate', 'in_force', '2016-01-01'::date, 'Indonesia', 'https://www.carrotsandsticks.org/policies/79_5', ARRAY['indonesia', 'mandatory', 'sdg16', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ebdc61fd-e084-5fd9-95fb-d2d6c3e6278f', 'Indonesia Salinan peraturan menteri badan usaha milik negara nomor', 'Salinan peraturan menteri badan usaha milik negara nomor: PER-09/NIBU/07/2015', 'This regulation is about the Partnership Programs and Community Development Programs of state-owned enterprises for small businesses and cooperatives. It states that as part of its Quarterly and Annual Report, state-owned enterprise should include a dedicated chapter regarding the partnership and community programs and its financial statement. The program report shall be audited together with the enterprise’s Annual Report.', 'This regulation is about the Partnership Programs and Community Development Programs of state-owned enterprises for small businesses and cooperatives. It states that as part of its Quarterly and Annual Report, state-owned enterprise should include a dedicated chapter regarding the partnership and community programs and its financial statement. The program report shall be audited together with the enterprise’s Annual Report.', 'This regulation is about the Partnership Programs and Community Development Programs of state-owned enterprises for small businesses and cooperatives. It states that as part of its Quarterly and Annual Report, state-owned enterprise should include a dedicated chapter regarding the partnership and community programs and its financial statement. The program report shall be audited together with the enterprise’s Annual Report.', 'Indonesia', 'climate', 'in_force', '2015-01-01'::date, 'Indonesia', 'https://www.carrotsandsticks.org/policies/79_1', ARRAY['indonesia', 'regulations', 'sdg17', 'sdg11', 'mandatory', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e32042a7-280f-5f0d-a501-50c069abc7eb', 'Indonesian National Carbon Accounting System (INCAS). Standard Methods', 'Indonesian National Carbon Accounting System (INCAS). Standard Methods for Estimation Greenhouse Gas Emissions from Sector Forestry in Indonesia (Version 1)', 'This publication describes in detail the standard methods of the Indonesian National Carbon Accounting System (INCAS) in quantifying net greenhouse gas (GHG) emissions for the forestry sector in Indonesia according to the TACCC principles, namely transparent, accurate, complete (complete), consistent (consistent) and comparable (comparable).', 'This publication describes in detail the standard methods of the Indonesian National Carbon Accounting System (INCAS) in quantifying net greenhouse gas (GHG) emissions for the forestry sector in Indonesia according to the TACCC principles, namely transparent, accurate, complete (complete), consistent (consistent) and comparable (comparable).', 'This publication describes in detail the standard methods of the Indonesian National Carbon Accounting System (INCAS) in quantifying net greenhouse gas (GHG) emissions for the forestry sector in Indonesia according to the TACCC principles, namely transparent, accurate, complete (complete), consistent (consistent) and comparable (comparable).', 'Indonesia', 'climate', 'in_force', '2015-01-01'::date, 'Indonesia', 'https://www.carrotsandsticks.org/policies/79_61', ARRAY['indonesia', 'sdg13', 'voluntary', 'disclosure', 'sdg15', 'voluntary_frameworks']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0dd6451b-378c-566d-90a0-723cba426fbe', 'Indonesian National Carbon Accounting System (INCAS). Standard Methods', 'Indonesian National Carbon Accounting System (INCAS). Standard Methods for Estimating Greenhouse Gas Emissions from Forests and Peatlands in Indonesia (Version 2)', 'This document (Annex) describes in detail the standard method developed by the Indonesian National Carbon Accounting System (INCAS) in calculating net greenhouse gas (GHG) emissions from the Indonesian forestry sector in a transparent, accurate, complete, consistent and reliable manner. compared (TACCC).', 'This document (Annex) describes in detail the standard method developed by the Indonesian National Carbon Accounting System (INCAS) in calculating net greenhouse gas (GHG) emissions from the Indonesian forestry sector in a transparent, accurate, complete, consistent and reliable manner. compared (TACCC).', 'This document (Annex) describes in detail the standard method developed by the Indonesian National Carbon Accounting System (INCAS) in calculating net greenhouse gas (GHG) emissions from the Indonesian forestry sector in a transparent, accurate, complete, consistent and reliable manner. compared (TACCC).', 'Indonesia', 'climate', 'in_force', '2015-01-01'::date, 'Indonesia', 'https://www.carrotsandsticks.org/policies/79_68', ARRAY['indonesia', 'sdg13', 'voluntary', 'disclosure', 'sdg15', 'voluntary_frameworks']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6e977830-413b-51f9-a3ec-b482be122ff6', 'Indonesia Number 2/POJK. about Good Corporate Governance for Insurance', 'Number 2/POJK.05/2014 about Good Corporate Governance for Insurance Companies', 'The Financial Services Authority Regulation Number 2/POJK.05/2014 concerning Good Corporate Governance for Insurance Companies was made as an effort to strengthen the national insurance industry, by improving the quality of the implementation of good corporate governance for insurance companies.', 'The Financial Services Authority Regulation Number 2/POJK.05/2014 concerning Good Corporate Governance for Insurance Companies was made as an effort to strengthen the national insurance industry, by improving the quality of the implementation of good corporate governance for insurance companies.', 'The Financial Services Authority Regulation Number 2/POJK.05/2014 concerning Good Corporate Governance for Insurance Companies was made as an effort to strengthen the national insurance industry, by improving the quality of the implementation of good corporate governance for insurance companies.', 'Indonesia', 'governance', 'in_force', '2014-01-01'::date, 'Indonesia', 'https://www.carrotsandsticks.org/policies/79_19', ARRAY['indonesia', 'regulations', 'mandatory', 'sdg16', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('56a8fc2d-9ca2-5ac2-a4ac-a739ba0b50f7', 'Roadmap for Sustainable Finance in Indonesia', 'Roadmap for Sustainable Finance in Indonesia 2015-2019', 'It lays down a comprehensive work plan for promoting sustainable finance for the period 2015-2019. The Roadmap will constitute an integral part of OJK’s Master Plan for Indonesia’s Financial Sector.', 'It lays down a comprehensive work plan for promoting sustainable finance for the period 2015-2019. The Roadmap will constitute an integral part of OJK’s Master Plan for Indonesia’s Financial Sector.', 'It lays down a comprehensive work plan for promoting sustainable finance for the period 2015-2019. The Roadmap will constitute an integral part of OJK’s Master Plan for Indonesia’s Financial Sector.', 'Indonesia', 'governance', 'in_force', '2014-01-01'::date, 'Indonesia', 'https://www.carrotsandsticks.org/policies/79_4', ARRAY['indonesia', 'mandatory', 'mandatory_regulations', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('069babad-d394-5dff-ba56-474fbd5b7e26', 'Indonesia Integrative Research Synthesis. Development of Forestry Greenhouse Gas', 'Integrative Research Synthesis. Development of Forestry Greenhouse Gas Emission Calculation (Inventory)', 'The Integrative Research Synthesis policy by Indonesia''s Ministry of Environment and Forestry focuses on developing Forestry Greenhouse Gas Emission Calculation (Inventory) to support sustainable landscape development. The policy aims to produce outputs like posters, journals, and policy recommendations. It is part of a strategic plan (RPI) aligned with the ministry''s priorities and the Forestry Research and Development Roadmap 2010-2025. The policy emphasizes collaboration with stakeholders and technical units nationwide, aiming to benefit decision-makers and practitioners in the forestry sector.', 'The Integrative Research Synthesis policy by Indonesia''s Ministry of Environment and Forestry focuses on developing Forestry Greenhouse Gas Emission Calculation (Inventory) to support sustainable landscape development. The policy aims to produce outputs like posters, journals, and policy recommendations. It is part of a strategic plan (RPI) aligned with the ministry''s priorities and the Forestry Research and Development Roadmap 2010-2025. The policy emphasizes collaboration with stakeholders and technical units nationwide, aiming to benefit decision-makers and practitioners in the forestry sector.', 'The Integrative Research Synthesis policy by Indonesia''s Ministry of Environment and Forestry focuses on developing Forestry Greenhouse Gas Emission Calculation (Inventory) to support sustainable landscape development. The policy aims to produce outputs like posters, journals, and policy recommendations. It is part of a strategic plan (RPI) aligned with the ministry''s priorities and the Forestry Research and Development Roadmap 2010-2025. The policy emphasizes collaboration with stakeholders and technical units nationwide, aiming to benefit decision-makers and practitioners in the forestry sector.', 'Indonesia', 'climate', 'in_force', '2014-01-01'::date, 'Indonesia', 'https://www.carrotsandsticks.org/policies/79_63', ARRAY['indonesia', 'sdg14', 'sdg13', 'regulations', 'sdg17', 'sdg9', 'mandatory', 'disclosure', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d2c29e26-a74e-574e-962c-3d8049ab3035', 'Indonesian Corporate Governance Manual. First Edition', 'The Indonesian Corporate Governance Manual. First Edition 2014', 'The Indonesian Corporate Governance Manual, first issued in 2014, aims to improve corporate governance practices in Indonesia by enhancing board roles, disclosure quality, and executive accountability. It serves as a benchmark against international best practices, emphasizing the importance of transparent and responsible business conduct. The manual covers various governance aspects like board structures, shareholder rights, disclosure, and internal controls. It is a key tool for directors, commissioners, policymakers, academics, and corporate governance experts to enhance market standards and build trust with stakeholders.', 'The Indonesian Corporate Governance Manual, first issued in 2014, aims to improve corporate governance practices in Indonesia by enhancing board roles, disclosure quality, and executive accountability. It serves as a benchmark against international best practices, emphasizing the importance of transparent and responsible business conduct. The manual covers various governance aspects like board structures, shareholder rights, disclosure, and internal controls. It is a key tool for directors, commissioners, policymakers, academics, and corporate governance experts to enhance market standards and build trust with stakeholders.', 'The Indonesian Corporate Governance Manual, first issued in 2014, aims to improve corporate governance practices in Indonesia by enhancing board roles, disclosure quality, and executive accountability. It serves as a benchmark against international best practices, emphasizing the importance of transparent and responsible business conduct. The manual covers various governance aspects like board structures, shareholder rights, disclosure, and internal controls. It is a key tool for directors, commissioners, policymakers, academics, and corporate governance experts to enhance market standards and build trust with stakeholders.', 'Indonesia', 'climate', 'in_force', '2014-01-01'::date, 'Indonesia', 'https://www.carrotsandsticks.org/policies/79_67', ARRAY['indonesia', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3dba5f90-d249-5818-8bbe-e3930c56bbec', 'Indonesia Rule No.KEP-431/BL/2012 concerning the obligation to submit annual', 'Rule No.KEP-431/BL/2012 concerning the obligation to submit annual reports for issuers of public companies', 'Important amendment in the rule is that disclosures on corporate social responsibility should include policies, types of programs, and expenditure on; environmental performance, labor practices, social and community empowerment, and product responsibility. This regulation concerns Annual Reporting for Publicly Listed Companies – superseding the Capital Markets Supervisory Agency Regulation No. X.K.6., 2006. Publicly listed companies can disclose the information in the annual report, in a separate sustainability report, or in a corporate social responsibility report, which need to be submitted simultaneously to the Capital Market Supervisory Agency.', 'Important amendment in the rule is that disclosures on corporate social responsibility should include policies, types of programs, and expenditure on; environmental performance, labor practices, social and community empowerment, and product responsibility. This regulation concerns Annual Reporting for Publicly Listed Companies – superseding the Capital Markets Supervisory Agency Regulation No. X.K.6., 2006. Publicly listed companies can disclose the information in the annual report, in a separate sustainability report, or in a corporate social responsibility report, which need to be submitted simultaneously to the Capital Market Supervisory Agency.', 'Important amendment in the rule is that disclosures on corporate social responsibility should include policies, types of programs, and expenditure on; environmental performance, labor practices, social and community empowerment, and product responsibility. This regulation concerns Annual Reporting for Publicly Listed Companies – superseding the Capital Markets Supervisory Agency Regulation No. X.K.6., 2006. Publicly listed companies can disclose the information in the annual report, in a separate sustainability report, or in a corporate social responsibility report, which need to be submitted simultaneously to the Capital Market Supervisory Agency.', 'Indonesia', 'climate', 'in_force', '2012-01-01'::date, 'Indonesia', 'https://www.carrotsandsticks.org/policies/79_11', ARRAY['indonesia', 'sdg11', 'mandatory', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f83225c4-a026-5ee8-b608-76db14979bfc', 'Indonesia Government Regulation . Number 47, 2012, Concerns, Social', 'Government Regulation of the Republic of Indonesia. Number 47, 2012, Concerns, Social and Environmental Responsibility of Limited Companies', 'The Government Regulation of the Republic of Indonesia Number 47, 2012, focuses on the social and environmental responsibility of limited liability companies. It aims to increase companies'' awareness of their responsibilities, strengthen existing social and environmental responsibility arrangements, and promote sustainable economic development. The regulation requires companies operating in natural resources to budget and account for social and environmental responsibilities as part of their expenses, ensuring propriety and fairness. It implements provisions from the 2007 Law on Limited Liability Companies to create harmonious relationships with local communities and society.', 'The Government Regulation of the Republic of Indonesia Number 47, 2012, focuses on the social and environmental responsibility of limited liability companies. It aims to increase companies'' awareness of their responsibilities, strengthen existing social and environmental responsibility arrangements, and promote sustainable economic development. The regulation requires companies operating in natural resources to budget and account for social and environmental responsibilities as part of their expenses, ensuring propriety and fairness. It implements provisions from the 2007 Law on Limited Liability Companies to create harmonious relationships with local communities and society.', 'The Government Regulation of the Republic of Indonesia Number 47, 2012, focuses on the social and environmental responsibility of limited liability companies. It aims to increase companies'' awareness of their responsibilities, strengthen existing social and environmental responsibility arrangements, and promote sustainable economic development. The regulation requires companies operating in natural resources to budget and account for social and environmental responsibilities as part of their expenses, ensuring propriety and fairness. It implements provisions from the 2007 Law on Limited Liability Companies to create harmonious relationships with local communities and society.', 'Indonesia', 'climate', 'in_force', '2012-01-01'::date, 'Indonesia', 'https://www.carrotsandsticks.org/policies/79_14', ARRAY['indonesia', 'sdg13', 'regulations', 'mandatory', 'sdg16', 'sdg12', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b10a6be6-de61-5b1a-9d46-09fd56098f25', 'Indonesia Government Regulation number 50, 2012 concerning Implementation', 'Government Regulation of the Republic of Indonesia number 50, 2012 concerning Implementation of Occupational Safety and Health Management System', 'The Government Regulation of the Republic of Indonesia number 50, 2012 focuses on the Implementation of Occupational Safety and Health Management System (SMK3). The policy aims to ensure workplace safety, prevent work accidents and occupational diseases, and improve productivity through structured safety and health protection measures. It outlines requirements for companies, including formulating K3 policies, implementing SMK3, conducting audits, and continuous improvement. The policy sets guidelines for SMK3 implementation based on national policies and regulations, with obligations for companies to comply with safety standards and regulations.', 'The Government Regulation of the Republic of Indonesia number 50, 2012 focuses on the Implementation of Occupational Safety and Health Management System (SMK3). The policy aims to ensure workplace safety, prevent work accidents and occupational diseases, and improve productivity through structured safety and health protection measures. It outlines requirements for companies, including formulating K3 policies, implementing SMK3, conducting audits, and continuous improvement. The policy sets guidelines for SMK3 implementation based on national policies and regulations, with obligations for companies to comply with safety standards and regulations.', 'The Government Regulation of the Republic of Indonesia number 50, 2012 focuses on the Implementation of Occupational Safety and Health Management System (SMK3). The policy aims to ensure workplace safety, prevent work accidents and occupational diseases, and improve productivity through structured safety and health protection measures. It outlines requirements for companies, including formulating K3 policies, implementing SMK3, conducting audits, and continuous improvement. The policy sets guidelines for SMK3 implementation based on national policies and regulations, with obligations for companies to comply with safety standards and regulations.', 'Indonesia', 'nature', 'in_force', '2012-01-01'::date, 'Indonesia', 'https://www.carrotsandsticks.org/policies/79_26', ARRAY['sdg8', 'indonesia', 'sdg14', 'regulations', 'mandatory', 'disclosure', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('fe2b56e6-84b4-5ea8-bff5-75eb980233aa', 'Indonesia Government Regulation Number 27, 2012, about Environmental Permission', 'Government Regulation of the Republic of Indonesia Number 27, 2012, about Environmental Permission', 'The Government Regulation of the Republic of Indonesia Number 27, 2012, focuses on environmental permission, requiring businesses and activities that may impact the environment to obtain Environmental Permits. It outlines the need for Environmental Impact Analysis (Amdal) or Environmental Management Efforts and Monitoring (UKL-UPL) for different types of activities. The policy emphasizes the importance of environmental protection and management in the decision-making process for businesses and activities.', 'The Government Regulation of the Republic of Indonesia Number 27, 2012, focuses on environmental permission, requiring businesses and activities that may impact the environment to obtain Environmental Permits. It outlines the need for Environmental Impact Analysis (Amdal) or Environmental Management Efforts and Monitoring (UKL-UPL) for different types of activities. The policy emphasizes the importance of environmental protection and management in the decision-making process for businesses and activities.', 'The Government Regulation of the Republic of Indonesia Number 27, 2012, focuses on environmental permission, requiring businesses and activities that may impact the environment to obtain Environmental Permits. It outlines the need for Environmental Impact Analysis (Amdal) or Environmental Management Efforts and Monitoring (UKL-UPL) for different types of activities. The policy emphasizes the importance of environmental protection and management in the decision-making process for businesses and activities.', 'Indonesia', 'climate', 'in_force', '2012-01-01'::date, 'Indonesia', 'https://www.carrotsandsticks.org/policies/79_27', ARRAY['indonesia', 'mandatory', 'regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3f095259-c59c-5882-812e-8c8dee7cb4a9', 'Indonesia Regulation of the State Minister of Environment', 'Regulation of the State Minister of Environment of the Republic of Indonesia, Number 16, 2012, Concerning Guidelines for Developing Environmental Documents', 'The Regulation of the State Minister of Environment of the Republic of Indonesia, Number 16, 2012, provides guidelines for developing environmental documents, including Environmental Impact Analysis (Amdal), Environmental Management Plans (RKL), and Environmental Monitoring Plans (RPL). It outlines the requirements for businesses and activities to assess and manage their environmental impacts, with specific formats and procedures for document preparation. The policy aims to ensure compliance with Environmental Protection and Management laws, assisting companies in decision-making processes related to their operations.', 'The Regulation of the State Minister of Environment of the Republic of Indonesia, Number 16, 2012, provides guidelines for developing environmental documents, including Environmental Impact Analysis (Amdal), Environmental Management Plans (RKL), and Environmental Monitoring Plans (RPL). It outlines the requirements for businesses and activities to assess and manage their environmental impacts, with specific formats and procedures for document preparation. The policy aims to ensure compliance with Environmental Protection and Management laws, assisting companies in decision-making processes related to their operations.', 'The Regulation of the State Minister of Environment of the Republic of Indonesia, Number 16, 2012, provides guidelines for developing environmental documents, including Environmental Impact Analysis (Amdal), Environmental Management Plans (RKL), and Environmental Monitoring Plans (RPL). It outlines the requirements for businesses and activities to assess and manage their environmental impacts, with specific formats and procedures for document preparation. The policy aims to ensure compliance with Environmental Protection and Management laws, assisting companies in decision-making processes related to their operations.', 'Indonesia', 'governance', 'in_force', '2012-01-01'::date, 'Indonesia', 'https://www.carrotsandsticks.org/policies/79_46', ARRAY['indonesia', 'voluntary', 'regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7e834014-8f1b-5d18-9769-304496da076d', 'Indonesia Central Government Government Regulation concerning Social and Environmental', 'Central Government Government Regulation concerning Social and Environmental Responsibility of Limited Liability Companies', 'The Central Government of Indonesia issued a 2012 policy regulating the social and environmental responsibilities of Limited Liability Companies (LLCs). The policy aims to promote sustainable economic development, improve quality of life, and protect the environment. LLCs engaged in natural resource-related activities must budget and report on social and environmental responsibilities. Non-compliance results in sanctions. The policy requires LLCs to integrate responsibility into their operations, with oversight by the Board of Directors and Commissioners. It emphasizes adherence to local values and culture. This mandatory policy aligns with Law Number 40 of 2007 and focuses on fostering harmonious and environmentally friendly business relationships.', 'The Central Government of Indonesia issued a 2012 policy regulating the social and environmental responsibilities of Limited Liability Companies (LLCs). The policy aims to promote sustainable economic development, improve quality of life, and protect the environment. LLCs engaged in natural resource-related activities must budget and report on social and environmental responsibilities. Non-compliance results in sanctions. The policy requires LLCs to integrate responsibility into their operations, with oversight by the Board of Directors and Commissioners. It emphasizes adherence to local values and culture. This mandatory policy aligns with Law Number 40 of 2007 and focuses on fostering harmonious and environmentally friendly business relationships.', 'The Central Government of Indonesia issued a 2012 policy regulating the social and environmental responsibilities of Limited Liability Companies (LLCs). The policy aims to promote sustainable economic development, improve quality of life, and protect the environment. LLCs engaged in natural resource-related activities must budget and report on social and environmental responsibilities. Non-compliance results in sanctions. The policy requires LLCs to integrate responsibility into their operations, with oversight by the Board of Directors and Commissioners. It emphasizes adherence to local values and culture. This mandatory policy aligns with Law Number 40 of 2007 and focuses on fostering harmonious and environmentally friendly business relationships.', 'Indonesia', 'climate', 'in_force', '2012-01-01'::date, 'Indonesia', 'https://www.carrotsandsticks.org/policies/79_7', ARRAY['indonesia', 'other sustainability policy', 'sdg13', 'regulations', 'mandatory', 'sdg16', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('caa3e3f1-b204-5107-abb6-6fc16b08ae9e', 'Indonesia Implementation of Action Plan for Reducing Greenhouse Gas', 'Guidelines for Implementation of Action Plan for Reducing Greenhouse Gas Emissions', 'The Guidelines for Implementation of the Action Plan for Reducing Greenhouse Gas Emissions in Indonesia, issued in 2011, aim to provide a framework for reducing greenhouse gas emissions through nationally appropriate mitigation actions. The document outlines policy directions, action plans by sector, and steps for developing emission reduction plans. It involves various government ministries, agencies, and external partners, emphasizing collaboration and technical support. The guidelines cover sectors like energy, transportation, land resources, and aim to support Indonesia''s efforts in mitigating climate change.', 'The Guidelines for Implementation of the Action Plan for Reducing Greenhouse Gas Emissions in Indonesia, issued in 2011, aim to provide a framework for reducing greenhouse gas emissions through nationally appropriate mitigation actions. The document outlines policy directions, action plans by sector, and steps for developing emission reduction plans. It involves various government ministries, agencies, and external partners, emphasizing collaboration and technical support. The guidelines cover sectors like energy, transportation, land resources, and aim to support Indonesia''s efforts in mitigating climate change.', 'The Guidelines for Implementation of the Action Plan for Reducing Greenhouse Gas Emissions in Indonesia, issued in 2011, aim to provide a framework for reducing greenhouse gas emissions through nationally appropriate mitigation actions. The document outlines policy directions, action plans by sector, and steps for developing emission reduction plans. It involves various government ministries, agencies, and external partners, emphasizing collaboration and technical support. The guidelines cover sectors like energy, transportation, land resources, and aim to support Indonesia''s efforts in mitigating climate change.', 'Indonesia', 'climate', 'in_force', '2011-01-01'::date, 'Indonesia', 'https://www.carrotsandsticks.org/policies/79_39', ARRAY['indonesia', 'sdg13', 'regulations', 'sdg7', 'sdg11', 'sdg17', 'disclosure', 'sdg15', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('93ad72c2-b11e-52de-8797-f862e5cf6a37', 'Indonesia Not only profit Principles for companies to carry', 'Not only profit Principles for companies to carry out social responsibility', 'The policy titled ''Not only profit Principles for companies to carry out social responsibility'' outlines principles for companies in Indonesia to conduct social responsibility. It emphasizes accountability, transparency, ethical behavior, compliance with regulations, human rights, and stakeholder inclusion. The policy aims to guide companies in balancing economic, social, and environmental factors for sustainable development. It encourages companies to go beyond legal requirements and prioritize public interest. The document targets implementers, observers, NGOs, academics, and government staff involved in corporate social responsibility.', 'The policy titled ''Not only profit Principles for companies to carry out social responsibility'' outlines principles for companies in Indonesia to conduct social responsibility. It emphasizes accountability, transparency, ethical behavior, compliance with regulations, human rights, and stakeholder inclusion. The policy aims to guide companies in balancing economic, social, and environmental factors for sustainable development. It encourages companies to go beyond legal requirements and prioritize public interest. The document targets implementers, observers, NGOs, academics, and government staff involved in corporate social responsibility.', 'The policy titled ''Not only profit Principles for companies to carry out social responsibility'' outlines principles for companies in Indonesia to conduct social responsibility. It emphasizes accountability, transparency, ethical behavior, compliance with regulations, human rights, and stakeholder inclusion. The policy aims to guide companies in balancing economic, social, and environmental factors for sustainable development. It encourages companies to go beyond legal requirements and prioritize public interest. The document targets implementers, observers, NGOs, academics, and government staff involved in corporate social responsibility.', 'Indonesia', 'nature', 'in_force', '2009-01-01'::date, 'Indonesia', 'https://www.carrotsandsticks.org/policies/79_53', ARRAY['guidance_frameworks', 'indonesia', 'sdg14', 'sdg10', 'sdg16', 'disclosure', 'sdg15', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d4a96225-a886-5204-93d9-bc69f5071a0a', 'Indonesia Government Regulation Number 43, 2008, about Ground Water', 'Government Regulation of the Republic of Indonesia Number 43, 2008, about Ground Water', 'Groundwater has an important role for the life and livelihood of Indonesian people, because it functions as one of the basic daily needs. Groundwater management is based on groundwater basins that are maintained based on groundwater management policies and groundwater management strategies.', 'Groundwater has an important role for the life and livelihood of Indonesian people, because it functions as one of the basic daily needs. Groundwater management is based on groundwater basins that are maintained based on groundwater management policies and groundwater management strategies.', 'Groundwater has an important role for the life and livelihood of Indonesian people, because it functions as one of the basic daily needs. Groundwater management is based on groundwater basins that are maintained based on groundwater management policies and groundwater management strategies.', 'Indonesia', 'climate', 'in_force', '2008-01-01'::date, 'Indonesia', 'https://www.carrotsandsticks.org/policies/79_25', ARRAY['indonesia', 'regulations', 'sdg7', 'mandatory', 'sdg6', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8a56164b-fced-515f-b78a-3975c76cc893', 'Indonesia Guide to Identification of High Conservation Value Areas', 'Guide to Identification of High Conservation Value Areas in Indonesia', 'The ''Guide to Identification of High Conservation Value Areas in Indonesia'' is a comprehensive document developed by the Consortium for the Revised HCV Toolkit Indonesia with support from USAID and RAFT. It aims to assist in identifying areas of significant biodiversity, landscape areas crucial for ecological dynamics, areas providing environmental services, and areas important for the cultural identity of local communities. The guide outlines the process, data collection methods, analysis, and stakeholder engagement required for assessing High Conservation Value areas in Indonesia.', 'The ''Guide to Identification of High Conservation Value Areas in Indonesia'' is a comprehensive document developed by the Consortium for the Revised HCV Toolkit Indonesia with support from USAID and RAFT. It aims to assist in identifying areas of significant biodiversity, landscape areas crucial for ecological dynamics, areas providing environmental services, and areas important for the cultural identity of local communities. The guide outlines the process, data collection methods, analysis, and stakeholder engagement required for assessing High Conservation Value areas in Indonesia.', 'The ''Guide to Identification of High Conservation Value Areas in Indonesia'' is a comprehensive document developed by the Consortium for the Revised HCV Toolkit Indonesia with support from USAID and RAFT. It aims to assist in identifying areas of significant biodiversity, landscape areas crucial for ecological dynamics, areas providing environmental services, and areas important for the cultural identity of local communities. The guide outlines the process, data collection methods, analysis, and stakeholder engagement required for assessing High Conservation Value areas in Indonesia.', 'Indonesia', 'climate', 'in_force', '2008-01-01'::date, 'Indonesia', 'https://www.carrotsandsticks.org/policies/79_32', ARRAY['indonesia', 'sdg17', 'mandatory', 'mandatory_regulations', 'disclosure', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b8ec5c82-7040-59dd-9a66-5240dfc0d0af', 'Indonesia Limited Liability Companies Law', 'Limited Liability Companies Law No. 40/2007', 'This law relates to Limited Liability Companies. Article 66 mandates all limited liability companies to include coverage of environmental and social responsibility programs in the annual report. Social and Environmental Responsibility as referred to in paragraph (1) shall constitutes the obligation of the Company which is budgeted and calculated as the cost of the Company, implementation of which shall be performed with due observance to the appropriateness and fairness. The Company which fails to perform its obligation as referred to in paragraph (1) shall be imposed with sanction in accordance with the provision of regulation.', 'This law relates to Limited Liability Companies. Article 66 mandates all limited liability companies to include coverage of environmental and social responsibility programs in the annual report. Social and Environmental Responsibility as referred to in paragraph (1) shall constitutes the obligation of the Company which is budgeted and calculated as the cost of the Company, implementation of which shall be performed with due observance to the appropriateness and fairness. The Company which fails to perform its obligation as referred to in paragraph (1) shall be imposed with sanction in accordance with the provision of regulation.', 'This law relates to Limited Liability Companies. Article 66 mandates all limited liability companies to include coverage of environmental and social responsibility programs in the annual report. Social and Environmental Responsibility as referred to in paragraph (1) shall constitutes the obligation of the Company which is budgeted and calculated as the cost of the Company, implementation of which shall be performed with due observance to the appropriateness and fairness. The Company which fails to perform its obligation as referred to in paragraph (1) shall be imposed with sanction in accordance with the provision of regulation.', 'Indonesia', 'climate', 'in_force', '2007-01-01'::date, 'Indonesia', 'https://www.carrotsandsticks.org/policies/79_9', ARRAY['indonesia', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f2399af0-b09d-5253-bb9c-dbd13eea9782', 'Indonesia''s Code of Good Corporate Governance', 'Indonesia''s Code of Good Corporate Governance 2006', 'This Code serves as fundamental guidance for companies to exercise their efforts in assuring long-term continuity within the corridor of appro­priate business ethics. Whilst the companies are expected to implement GCG voluntarily, business associations and other institutions are expected to be active in socializing and promoting GCG implementation at a larger scale. The regulators are also expected to adopt basic principles in this Code as reference in formulating their respective regulation to broaden GCG implementation in Indonesia.', 'This Code serves as fundamental guidance for companies to exercise their efforts in assuring long-term continuity within the corridor of appro­priate business ethics. Whilst the companies are expected to implement GCG voluntarily, business associations and other institutions are expected to be active in socializing and promoting GCG implementation at a larger scale. The regulators are also expected to adopt basic principles in this Code as reference in formulating their respective regulation to broaden GCG implementation in Indonesia.', 'This Code serves as fundamental guidance for companies to exercise their efforts in assuring long-term continuity within the corridor of appro­priate business ethics. Whilst the companies are expected to implement GCG voluntarily, business associations and other institutions are expected to be active in socializing and promoting GCG implementation at a larger scale. The regulators are also expected to adopt basic principles in this Code as reference in formulating their respective regulation to broaden GCG implementation in Indonesia.', 'Indonesia', 'governance', 'in_force', '2006-01-01'::date, 'Indonesia', 'https://www.carrotsandsticks.org/policies/79_8', ARRAY['indonesia', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4bed3a25-06bd-5757-9174-6e46bdab24fd', 'Indonesia Circular letter of the Minister of Manpower', 'Circular letter of the Minister of Manpower and Transmigration of the Republic of Indonesia number se.140/men/pkk-kk/ii/2004 concerning fulfillment of occupational safety and health requirements in the chemical industry with great potential hazards', 'Circular letter concerning the fulfillment of occupational safety and health requirements in the chemical industry.', 'Circular letter concerning the fulfillment of occupational safety and health requirements in the chemical industry.', 'Circular letter concerning the fulfillment of occupational safety and health requirements in the chemical industry.', 'Indonesia', 'social', 'in_force', '2004-01-01'::date, 'Indonesia', 'https://www.carrotsandsticks.org/policies/79_17', ARRAY['sdg8', 'indonesia', 'other sustainability policy', 'mandatory', 'mandatory_regulations', 'sdg9', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('cf7c9802-7a15-5a70-8997-9d9bf3e8893f', 'Indonesian Code for Good Corporate Governance', 'Indonesian Code for Good Corporate Governance 2001', 'The objective of the Code is to provide a guide to excellence in corporate governance for the business world which has drawn on international best practice in corporate governance appropriately adjusted to suit the Indonesian legal and regulatory environment. The good corporate governance principles as set out in the Code are intended to be implemented as soon as possible.', 'The objective of the Code is to provide a guide to excellence in corporate governance for the business world which has drawn on international best practice in corporate governance appropriately adjusted to suit the Indonesian legal and regulatory environment. The good corporate governance principles as set out in the Code are intended to be implemented as soon as possible.', 'The objective of the Code is to provide a guide to excellence in corporate governance for the business world which has drawn on international best practice in corporate governance appropriately adjusted to suit the Indonesian legal and regulatory environment. The good corporate governance principles as set out in the Code are intended to be implemented as soon as possible.', 'Indonesia', 'governance', 'in_force', '2001-01-01'::date, 'Indonesia', 'https://www.carrotsandsticks.org/policies/79_13', ARRAY['indonesia', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('890733db-fb64-5ff2-a398-35f531318333', 'International <IR> Framework (2021) by the International Integrated', 'The International <IR> Framework (2021) by the International Integrated Reporting Council (IIRC).', 'The International <IR> Framework establishes principles for integrated reporting (<IR>), aiming to provide a holistic view of how organizations create, preserve, or erode value over time. It encourages businesses to improve corporate transparency, long-term strategic thinking, and stakeholder communication by incorporating financial and non-financial factors into reporting.

Key provisions include:

Integrated Thinking & Value Creation:
Encourages companies to integrate financial, environmental, social, and governance (ESG) considerations.
Defines value creation as linked to six capitals: financial, manufactured, intellectual, human, social & relationship, and natural capital.
Guiding Principles for Integrated Reporting:
Strategic focus & future orientation – Reports must connect business strategy with long-term value creation.
Connectivity of information – Ensures a holistic view of risks, opportunities, and stakeholder impacts.
Stakeholder relationships – Encourages businesses to consider stakeholder needs in decision-making.
Materiality – Requires disclosure of matters that significantly impact value creation.
Conciseness & reliability – Reports must be clear, balanced, and verifiable.
Consistency & comparability – Ensures alignment across reporting periods and with industry standards.
Key Content Elements for Reporting:
Organizational overview & governance – Details on leadership, risk management, and corporate structure.
Business model – Explanation of how the company operates and generates value.
Risks, opportunities & performance – Highlights sustainability challenges and financial performance.
Outlook & resource allocation – Defines long-term goals and strategic priorities.
Application & Compliance:
The framework is principles-based, allowing flexibility in reporting while maintaining consistency with global ESG disclosure frameworks.
Applies to public and private sector organizations, including corporations, financial institutions, and government entities.
The 2021 revision strengthens sustainability integration, ensuring alignment with emerging global standards such as IFRS Sustainability Disclosure Standards and the EU Corporate Sustainability Reporting Directive (CSRD).', 'The International <IR> Framework establishes principles for integrated reporting (<IR>), aiming to provide a holistic view of how organizations create, preserve, or erode value over time. It encourages businesses to improve corporate transparency, long-term strategic thinking, and stakeholder communication by incorporating financial and non-financial factors into reporting.

