INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('822b9aec-49b6-5a42-b392-27ab2d6e431a', 'ICMM Social and Economic Reporting Framework and Guidance', 'Social and Economic Reporting Framework and Guidance, 2022', 'This purpose of this framework is to provide a common approach for member companies to report on their social and economic contributions, impacts, and dependencies. The framework is based on eight thematic areas, including governance, employment, community well-being, and economic impacts. It provides guidance on reporting indicators, data collection, and verification, and encourages companies to report their performance in a transparent and consistent manner. The ICMM Social and Economic Reporting Framework and Guidance is intended to help mining and metals companies assess and communicate their contributions to sustainable development and to demonstrate their social and economic value to stakeholders. It is also intended to promote accountability and transparency in the mining sector, and to enhance the industry''s social license to operate.', 'This purpose of this framework is to provide a common approach for member companies to report on their social and economic contributions, impacts, and dependencies. The framework is based on eight thematic areas, including governance, employment, community well-being, and economic impacts. It provides guidance on reporting indicators, data collection, and verification, and encourages companies to report their performance in a transparent and consistent manner. The ICMM Social and Economic Reporting Framework and Guidance is intended to help mining and metals companies assess and communicate their contributions to sustainable development and to demonstrate their social and economic value to stakeholders. It is also intended to promote accountability and transparency in the mining sector, and to enhance the industry''s social license to operate.', 'This purpose of this framework is to provide a common approach for member companies to report on their social and economic contributions, impacts, and dependencies. The framework is based on eight thematic areas, including governance, employment, community well-being, and economic impacts. It provides guidance on reporting indicators, data collection, and verification, and encourages companies to report their performance in a transparent and consistent manner. The ICMM Social and Economic Reporting Framework and Guidance is intended to help mining and metals companies assess and communicate their contributions to sustainable development and to demonstrate their social and economic value to stakeholders. It is also intended to promote accountability and transparency in the mining sector, and to enhance the industry''s social license to operate.', 'ICMM', 'climate', 'in_force', '2022-01-01'::date, 'International Council on Mining and Metals', 'https://www.icmm.com/en-gb/our-principles/validation/social-and-economic-reporting', ARRAY['sdg8', 'sdg3', 'icmm', 'sdg11', 'voluntary', 'sdg16', 'disclosure', 'sdg9', 'voluntary_frameworks']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6c7452d1-9d1f-560c-a52e-127bfd8cb620', 'IFC Performance Standards on Environmental and Social Sustainability', 'Performance Standards on Environmental and Social Sustainability', 'IFC''s Sustainability Framework articulates the Corporation''s strategic commitment to sustainable development, and is an integral part of IFC''s approach to risk management. The Sustainability Framework comprises IFC''s Policy and Performance Standards on Environmental and Social Sustainability, and IFC''s Access to Information Policy.', 'IFC''s Sustainability Framework articulates the Corporation''s strategic commitment to sustainable development, and is an integral part of IFC''s approach to risk management. The Sustainability Framework comprises IFC''s Policy and Performance Standards on Environmental and Social Sustainability, and IFC''s Access to Information Policy.', 'IFC''s Sustainability Framework articulates the Corporation''s strategic commitment to sustainable development, and is an integral part of IFC''s approach to risk management. The Sustainability Framework comprises IFC''s Policy and Performance Standards on Environmental and Social Sustainability, and IFC''s Access to Information Policy.', 'IFC', 'climate', 'in_force', '2012-01-01'::date, 'International Finance Corporation', 'https://www.ifc.org/content/dam/ifc/doc/mgrt/ifc-performance-standards.pdf', ARRAY['sdg13', 'voluntary', 'sdg16', 'sdg12', 'disclosure', 'voluntary_frameworks', 'ifc']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7fa58fe7-eb30-5cad-ade9-f2067077766f', 'IFC International Finance Corporation’s Performance Standards on Social &', 'International Finance Corporation’s Performance Standards on Social & Environmental Sustainability', 'International Finance Corporation (IFC) applies the Performance Standards to manage social and environmental risks and impacts and to enhance development opportunities in its private sector financing in its member countries eligible for financing. The Performance Standards may also be applied by other financial institutions electing to apply them to projects in emerging markets.', 'International Finance Corporation (IFC) applies the Performance Standards to manage social and environmental risks and impacts and to enhance development opportunities in its private sector financing in its member countries eligible for financing. The Performance Standards may also be applied by other financial institutions electing to apply them to projects in emerging markets.', 'International Finance Corporation (IFC) applies the Performance Standards to manage social and environmental risks and impacts and to enhance development opportunities in its private sector financing in its member countries eligible for financing. The Performance Standards may also be applied by other financial institutions electing to apply them to projects in emerging markets.', 'IFC', 'climate', 'in_force', '2006-01-01'::date, 'International Finance Corporation', 'https://www.ifc.org/content/dam/ifc/doc/mgrt/ifc-performance-standards.pdf', ARRAY['sdg13', 'voluntary', 'sdg16', 'sdg12', 'disclosure', 'voluntary_frameworks', 'ifc']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f944d0b9-8602-50b2-b286-fc1f0d8e3804', 'IFRS Exposure Draft Amendments to Greenhouse Gas Emissions', 'IFRS Exposure Draft Amendments to Greenhouse Gas Emissions Disclosures Proposed amendments to IFRS S2', 'This policy was published in 2025 by International Financial Reporting Standards Foundation (IFRS). It addresses sustainability and corporate responsibility requirements.', 'This policy was published in 2025 by International Financial Reporting Standards Foundation (IFRS). It addresses sustainability and corporate responsibility requirements.', 'This policy was published in 2025 by International Financial Reporting Standards Foundation (IFRS). It addresses sustainability and corporate responsibility requirements.', 'IFRS', 'climate', 'in_force', '2025-01-01'::date, 'International Financial Reporting Standards Foundation (IFRS)', 'https://www.carrotsandsticks.org/policies/408_5', ARRAY['ifrs', 'mandatory', 'mandatory_regulations', 'sdg13']::text[]) ON CONFLICT (id) DO NOTHING;
